"""Build the browsable static gallery and Markdown cards from one catalog and run."""
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'docs/research/kline_pattern_library_20260928'
LEGEND='''t=0 是待判断的已完成交易日，[-1] 是前一条来源日记录；无效/零成交记录不压缩，相关值留空。o/h/l/c/v=同口径开高低收量。阳阴由 c−o 决定；涨跌由 c−c[-1] 决定，不能混用。body=|c−o|，range=h−l，upper=h−max(o,c)，lower=min(o,c)−l。公式中的 & 表示并且、| 表示或者，必须用括号；所有条件逐项 AND，不用乘法替代逻辑。body_avg=此前20根实体均值；vbase=此前20根均量；v5=此前5根均量，均排除当前。MA为完整窗口简单均值。MACD：12/26期EMA以各自窗口SMA起种，DEA为DIF的9期EMA，hist=DIF−DEA。RSI14：涨跌额分别以14期均值起种，再按Wilder的1/14递推；全平为50。ATR14为Wilder真实波幅。BOLL为MA20±2×20期总体标准差；bw=(上−下)/中。bw_q20为此前120根带宽的20%分位。缺数保持未知，禁止补0或填充价格。'''
PIVOTS='''lo/hi 为价格低/高极值，rlo/rhi 为RSI低/高极值：用左2根+自身+右2根的严格唯一极值，直到右2根完成才发布。p1/p2=最近两个已确认极值，p3=更早第三个；i1/i2为原输入位置；dif1/dif2、rsi1/rsi2为同一价格极值当日指标。sep为两极值间距，要求5–60根；age为第二极值距当前，最多30根；event=当前恰好确认新极值。neck为两低点间最高价或两高点间最低价；RSI版本用RSI中间极值。所有本地长度、相似容差、分位数均为预先冻结的v1研究约定，没有在本次命中样本上调优。'''
def main():
 pats=json.loads((OUT/'patterns.json').read_text());results=json.loads((OUT/'results.json').read_text());stats={x['id']:x for x in results};cases={x['case_id']:x for x in map(json.loads,(OUT/'cases.jsonl').read_text().splitlines())};run=json.loads((OUT/'run_manifest.json').read_text());md=['# 日K与指标形态库 v1','','62个去重定义：原资料归并37、新增25。每条公式都是本次执行的同一来源；全篇为研究口径，不等于标准教材逐字定义。','',LEGEND,'',PIVOTS,''];cards=[]
 for p in pats:
  s=stats[p['id']];items=[cases[c] for c in s['case_ids']];first=next((c for c in items if c['matched']),None)
  md.extend([f'## {p["name"]} · `{p["id"]}`','',p['description'],'',f'类型：{p["family"]}；来源范围：{p["origin"]}；[参考]({p["source"]})。','', '```text',p['formula'],'```','',f'全扫描命中 {s["total_matches"]} 次；本次验证 {s["tested_hits"]} 组正例。命中均时：缓存判断 {s["mean_cached_match_ms"]:.4f} ms；重算共享特征+判断 {s["mean_prepare_and_match_ms"]:.2f} ms；绘图 {s["mean_render_ms"]:.2f} ms。',''])
  if first:md.extend([f'![{p["name"]}真实日线示例]({p.get("example_image", first["image"])})',''])
  gallery=[]
  for c in items:
   label='公式命中' if c['matched'] else '近似反例（未计时）'
   failed=[e['label'] for e in c['evidence'] if e['result'] is False]
   md.append(f'- {label}：{c["stock_code"]} {c["signal_date"]}，[K图]({c["image"]})'+('；不满足：'+','.join(failed) if failed else ''))
   evidence=''.join('<li>'+html.escape(e['label'])+'：'+('满足' if e['result'] else '未满足/未知')+'<code>'+html.escape(e['expr'])+'</code><small>'+html.escape(json.dumps(e['operands'],ensure_ascii=False))+'</small></li>' for e in c['evidence'])
   gallery.append(f'<details><summary>{label} · {c["stock_code"]} · {c["signal_date"]}</summary><a href="{c["image"]}"><img loading="lazy" src="{c["image"]}" alt="{html.escape(p["name"])}"></a><ul>{evidence}</ul></details>')
  md.append('')
  conds=''.join('<li>'+html.escape(e['label'])+'<code>'+html.escape(e['expr'])+'</code></li>' for e in p['conditions'])
  cards.append(f'''<article data-search="{html.escape(p['name']+' '+p['id']+' '+p['family']+' '+p['origin'])}"><div class="tag">{p['origin']} · {p['family']}</div><h2>{html.escape(p['name'])}</h2><small>{p['id']} · v1</small><p>{html.escape(p['description'])}</p><img loading="lazy" src="{p.get('example_image', first['image'])}" alt="{html.escape(p['name'])}"><details><summary>展开判定条件</summary><ol>{conds}</ol><p><a href="{p['source']}">定义参考</a>；实际阈值按本页v1约定。</p></details><p class="timing">回扫命中 {s['total_matches']} · 抽验 {s['tested_hits']}<br>缓存判定 {s['mean_cached_match_ms']:.3f} ms · 从历史重算 {s['mean_prepare_and_match_ms']:.1f} ms · 绘图 {s['mean_render_ms']:.1f} ms</p>{''.join(gallery)}</article>''')
 (OUT/'catalog.md').write_text('\n'.join(md))
 css='''body{margin:0;background:#f2f5f9;color:#243349;font:15px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header,main,footer{max-width:1300px;margin:auto;padding:30px}header{padding-bottom:12px}h1{font-size:34px;margin:0}h2{font-size:23px;margin:5px 0}small{color:#657185;overflow-wrap:anywhere}input{font:inherit;width:min(95%,700px);padding:12px 16px;border:1px solid #cbd5e1;border-radius:8px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(460px,1fr));gap:24px;padding-top:8px}article{background:white;border:1px solid #d9e2ee;border-radius:12px;padding:24px;overflow:hidden}article img{width:100%;height:auto}.tag{font-size:12px;color:#167e79;font-weight:700}details{border-top:1px solid #e2e8f0;padding:10px 0}summary{cursor:pointer;font-weight:600}code{display:block;font:12px/1.6 ui-monospace,monospace;background:#f5f7fa;padding:7px;overflow-wrap:anywhere}li{margin:8px 0}.timing{font-size:13px;background:#edf6fa;padding:10px}a{color:#2264a8}aside{background:#fff4d9;padding:14px;border-radius:8px}article[hidden]{display:none}@media(max-width:600px){main{grid-template-columns:1fr;padding:12px}header{padding:20px}article{padding:16px}}'''
 (OUT/'index.html').write_text(f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>日K与指标形态库 v1</title><style>{css}</style><header><div class="tag">FIN AGENT · 研究资产 · 2026-09-28</div><h1>日K与指标形态库</h1><p>62个去重定义 · 24只股票 · {run['workload']['bars']:,}根日K · {run['workload']['matched_samples']}组命中抽验 · {run['workload']['near_miss_samples']}组近似反例</p><aside>这是“符合所列公式”的识别实验。小样本重放通过不等于独立识别准确率，更不是收益回测。图片均由数据库真实行情统一重绘，截止信号当日。计时不含被排除样本、取数或模型调用。</aside><p><a href="README.md">使用与实测报告</a> · <a href="original_coverage.md">30条原资料去重/未决事项</a> · <a href="patterns.json">机器可读定义</a></p><details><summary>统一符号、计算与峰谷确认口径</summary><p>{LEGEND}</p><p>{PIVOTS}</p></details><p><input id="search" placeholder="搜索形态、MACD、RSI、新增…" aria-label="搜索形态"> <span id="count">62 条</span></p></header><main>{''.join(cards)}</main><footer>公开行情研究样本；当前源数据快照，不冒充历史当时版本。所有公式与样例均可通过仓库研究脚本重放。</footer><script>document.getElementById('search').addEventListener('input',e=>{{let n=0;const q=e.target.value.trim().toLowerCase();document.querySelectorAll('article').forEach(a=>{{a.hidden=!a.dataset.search.toLowerCase().includes(q);if(!a.hidden)n++}});document.getElementById('count').textContent=n+' 条'}})</script></html>''')
if __name__=='__main__':main()
